const rows = $input.all().map(i => i.json);
const token = $('Get Meta credentials').first().json.system_user_token;
const out = [];
for (const row of rows) {
  if (!row.meta_campaign_id) continue;
  out.push({ json: {
    campaignRowId: row.id,
    metaCampaignId: row.meta_campaign_id,
    metaAdsetId: row.meta_adset_id || null,
    campaignName: row.campaign_name,
    status: row.status,
    objective: row.objective,
    dailyBudgetUsd: row.daily_budget_usd,
    accessToken: token,
  } });
}
return out;

const campaigns = $('Filter synced campaigns').all();
const searches = $('Fetch insights').all();
const fallbackDate = new Date(Date.now() - 86400000).toISOString().slice(0, 10);

// action_type values that count as a 'result', in priority order. Meta varies
// by account/objective — mirror the Phase-1 reporting agent's lead matching.
const RESULT_TYPES = ['lead','onsite_conversion.lead_grouped','offsite_conversion.fdt_lead','leadgen.other','onsite_web_lead','offsite_conversion.fdt_purchase','purchase','omni_purchase','link_click'];

function pickResults(actions) {
  if (!Array.isArray(actions)) return 0;
  for (const t of RESULT_TYPES) {
    const hit = actions.find(a => a.action_type === t);
    if (hit) return Number(hit.value || 0);
  }
  return 0;
}

return campaigns.map((c, i) => {
  const data = (searches[i] && searches[i].json.data) || [];
  const row = data[0];
  const spend = row ? Number(row.spend || 0) : 0;
  const results = row ? pickResults(row.actions) : 0;
  const roasArr = row && Array.isArray(row.purchase_roas) ? row.purchase_roas : [];
  const roas = roasArr.length ? Number(roasArr[0].value || 0) : null;
  return { json: {
    campaign_id: c.json.campaignRowId,
    date: row ? (row.date_start || fallbackDate) : fallbackDate,
    spend,
    results,
    cost_per_result: results > 0 ? spend / results : null,
    impressions: row ? Number(row.impressions || 0) : 0,
    clicks: row ? Number(row.clicks || 0) : 0,
    cpm: row ? Number(row.cpm || 0) : 0,
    cpc: row ? Number(row.cpc || 0) : 0,
    ctr: row ? Number(row.ctr || 0) : 0,
    frequency: row ? Number(row.frequency || 0) : 0,
    roas,
  } };
});

const campaigns = $('Filter synced campaigns').all();
const searches = $('Fetch recommendations').all();
const out = [];
campaigns.forEach((c, i) => {
  const campaignRowId = c.json.campaignRowId;
  const metaCampaignId = c.json.metaCampaignId;
  const recs = (searches[i] && searches[i].json && searches[i].json.recommendations) || [];
  for (const r of recs) {
    out.push({ json: {
      campaign_id: campaignRowId,
      type: r.code || r.title || 'recommendation',
      dollars_recoverable: null,
      resource_name: metaCampaignId + ':' + (r.code || r.title || Math.random().toString(36).slice(2)),
      status: 'open',
    } });
  }
});
return out;

const campaigns = $('Filter synced campaigns').all();
const configs = $('Fetch campaign config').all();
const budgets = $('Fetch adset budget').all();
const statusMap = { ACTIVE: 'active', PAUSED: 'paused' };
const out = [];
campaigns.forEach((c, i) => {
  const cfg = (configs[i] && configs[i].json) || {};
  const budRaw = (budgets[i] && budgets[i].json) || {};
  // Direct ad set fetch returns the object itself; the campaign's /adsets
  // fallback (used when meta_adset_id was never captured) returns
  // { data: [...] } instead — normalize both to one object.
  const bud = Array.isArray(budRaw.data) ? (budRaw.data[0] || {}) : budRaw;
  if (!cfg.status && !cfg.effective_status) return; // campaign gone / no data
  const raw = cfg.effective_status && ['CAMPAIGN_PAUSED','PAUSED','ADSET_PAUSED'].includes(cfg.effective_status) ? 'PAUSED' : cfg.status;
  const minor = Number(bud.daily_budget || cfg.daily_budget || 0);
  const geo = (bud.targeting && bud.targeting.geo_locations) || {};
  // Meta targeting isn't always country-level — a local-service campaign
  // commonly targets specific regions/cities instead (confirmed live: a
  // 'KW/Cambridge/Guelph' campaign had no geo_locations.countries at all).
  // targeting_countries is really just "targeting places" at this point;
  // fall back to region/city names so the dashboard shows something real
  // instead of a blank that reads as broken.
  let places = null;
  if (Array.isArray(geo.countries) && geo.countries.length) {
    places = geo.countries;
  } else if (Array.isArray(geo.regions) && geo.regions.length) {
    places = geo.regions.map(r => r.name).filter(Boolean);
  } else if (Array.isArray(geo.cities) && geo.cities.length) {
    places = geo.cities.map(c => c.name).filter(Boolean);
  }
  const targeting = bud.targeting || {};
  out.push({ json: {
    campaignRowId: c.json.campaignRowId,
    status: statusMap[raw] || 'paused',
    dailyBudgetUsd: minor > 0 ? minor / 100 : c.json.dailyBudgetUsd,
    metaAdsetId: bud.id || c.json.metaAdsetId || null,
    targetingCountries: places,
    targetingAgeMin: targeting.age_min != null ? targeting.age_min : null,
    targetingAgeMax: targeting.age_max != null ? targeting.age_max : null,
  } });
});
return out;

const campaigns = $('Filter synced campaigns').all();
const metricsRows = $('Build metrics row').all();
const allRecs = $('Build recommendation items').all().map(i => i.json).filter(r => r && r.campaign_id);
return campaigns.map((c, i) => {
  const m = (metricsRows[i] && metricsRows[i].json) || {};
  const recRows = allRecs.filter(r => r.campaign_id === c.json.campaignRowId);
  const roas = m.roas != null ? m.roas : null;
  const recsText = recRows.length ? recRows.map(r => '- ' + r.type).join('\n') : 'None currently open.';
  return { json: {
    campaignRowId: c.json.campaignRowId,
    campaignName: c.json.campaignName,
    status: c.json.status,
    objective: c.json.objective,
    dailyBudgetUsd: c.json.dailyBudgetUsd,
    date: m.date,
    spend: m.spend,
    results: m.results,
    costPerResult: m.cost_per_result,
    roas,
    recommendationsText: recsText,
  } };
});

const aiOutputs = $input.all();
const contexts = $('Build suggestion context').all();
return aiOutputs.map((item, i) => {
  const output = item.json.output || {};
  const hasAction = output.action_type && output.action_type !== 'none';
  const proposedAction = hasAction ? {
    action_type: output.action_type,
    daily_budget_usd: output.action_type === 'update_daily_budget' ? output.daily_budget_usd : null,
    reason: output.reason,
  } : null;
  return { json: {
    campaignRowId: (contexts[i] && contexts[i].json.campaignRowId) || null,
    shouldPost: !!output.should_post,
    message: output.message,
    proposedAction,
    actionStatus: hasAction ? 'proposed' : null,
  } };
});

const clients = $('Get all clients').all().map(i => i.json).filter(c => c && c.id);
const campaigns = $('Get all campaigns').all().map(i => i.json).filter(c => c && c.id);
const tracked = new Set(campaigns.map(c => String(c.meta_ad_account_id || '').replace(/^act_/, '')));

// Map an account_id -> the single client that owns it, matched on
// clients.meta_ad_account_id. Skip accounts no client claims and accounts with
// no client (can't attribute a discovered campaign safely).
const clientByAcct = new Map();
for (const cl of clients) {
  const acct = String(cl.meta_ad_account_id || '').replace(/^act_/, '');
  if (!acct) continue;
  if (clientByAcct.has(acct)) { clientByAcct.set(acct, null); continue; } // ambiguous
  clientByAcct.set(acct, cl.id);
}

const accts = ($json.data || []);
const out = [];
for (const a of accts) {
  const acctId = String(a.account_id || a.id || '').replace(/^act_/, '');
  if (!acctId) continue;
  const clientId = clientByAcct.get(acctId);
  if (!clientId) continue; // no client, or ambiguous -> skip discovery
  out.push({ json: {
    adAccountId: 'act_' + acctId,
    clientId,
    accessToken: $('Get Meta credentials').first().json.system_user_token,
    alreadyTracked: tracked.has(acctId),
  } });
}
return out;

const accounts = $('Resolve accounts to clients').all();
const searches = $input.all();
const known = new Set($('Get all campaigns').all().map(i => i.json).map(c => c && c.meta_campaign_id).filter(Boolean).map(String));
const statusMap = { ACTIVE: 'active', PAUSED: 'paused' };
const out = [];
searches.forEach((s, i) => {
  const acct = accounts[i] && accounts[i].json;
  if (!acct) return;
  const rows = (s.json && s.json.data) || [];
  for (const r of rows) {
    if (!r.id || known.has(String(r.id))) continue;
    const minor = Number(r.daily_budget || 0);
    out.push({ json: {
      clientId: acct.clientId,
      adAccountId: acct.adAccountId,
      campaignName: r.name,
      status: statusMap[r.status] || 'paused',
      objective: r.objective || 'OUTCOME_LEADS',
      dailyBudgetUsd: minor > 0 ? minor / 100 : null,
      metaCampaignId: String(r.id),
    } });
  }
});
return out;
